import React, { useEffect, useState } from "react";
import { motion } from "framer-motion";

const WorkerSplash = ({ onComplete }) => {
  const [isZooming, setIsZooming] = useState(false);

  useEffect(() => {
    // Phase 1: Mechanical Assembly (0s - 2.5s)
    // Phase 2: Warp Zoom (2.8s)
    const zoomTimer = setTimeout(() => setIsZooming(true), 2800);
    const completeTimer = setTimeout(onComplete, 3600);

    return () => { 
      clearTimeout(zoomTimer); 
      clearTimeout(completeTimer); 
    };
  }, [onComplete]);

  const letterVariants = {
    initialLeft: { x: -150, opacity: 0, skewX: -20 },
    initialCenter: { scale: 0, opacity: 0 },
    initialRight: { x: 150, opacity: 0, skewX: 20 },
    animate: { x: 0, y: 0, scale: 1, opacity: 1, skewX: 0 }
  };

  return (
    <div className="h-screen w-full bg-[#050505] flex items-center justify-center overflow-hidden font-sans select-none">

      {/* Subtly moving background grid */}
      <motion.div 
        initial={{ opacity: 0 }}
        animate={{ opacity: 0.05 }}
        className="absolute inset-0 bg-[grid-white_30px_30px] [mask-image:radial-gradient(ellipse_at_center,black,transparent)]" 
      />

      <div className={`relative transition-transform duration-700 ${isZooming ? "animate-warp" : "scale-100"}`}>
        <div className="flex items-center justify-center gap-2 md:gap-6">

          {/* First T - Mechanical Slide */}
          <motion.span 
            variants={letterVariants}
            initial="initialLeft"
            animate="animate"
            transition={{ duration: 0.6, ease: [0.22, 1, 0.36, 1], delay: 0.3 }}
            className="text-8xl md:text-[12rem] font-[1000] italic text-white tracking-tighter drop-shadow-[0_10px_20px_rgba(255,255,255,0.1)]"
          >
            T
          </motion.span>

          {/* The 2 - Scale Explosion with Brand Shimmer */}
          <motion.span 
            variants={letterVariants}
            initial="initialCenter"
            animate="animate"
            transition={{ 
              type: "spring", 
              stiffness: 200, 
              damping: 20, 
              delay: 0.6 
            }}
            className="text-8xl md:text-[12rem] font-[1000] italic text-shimmer tracking-tighter"
          >
            2
          </motion.span>

          {/* Second T - Mechanical Slide */}
          <motion.span 
            variants={letterVariants}
            initial="initialRight"
            animate="animate"
            transition={{ duration: 0.6, ease: [0.22, 1, 0.36, 1], delay: 0.4 }}
            className="text-8xl md:text-[12rem] font-[1000] italic text-white tracking-tighter drop-shadow-[0_10px_20px_rgba(255,255,255,0.1)]"
          >
            T
          </motion.span>
        </div>

        {/* Dynamic Tracking Line */}
        <motion.div 
          initial={{ opacity: 0, scaleX: 0 }}
          animate={{ opacity: 0.6, scaleX: 1 }}
          transition={{ duration: 1, delay: 1.2 }}
          className="mt-2 h-[2px] w-full bg-gradient-to-r from-transparent via-[#CAD23C] to-transparent"
        />

        <motion.p 
          initial={{ opacity: 0, y: 10 }}
          animate={{ opacity: 0.3, y: 0 }}
          transition={{ duration: 0.8, delay: 1.5 }}
          className="mt-4 text-center text-white text-[11px] font-black uppercase tracking-[1.2em] ml-[1.2em]"
        >
          Authorized_Only
        </motion.p>
      </div>

      {/* Industrial Glitch Layer */}
      <div className="absolute inset-0 pointer-events-none opacity-[0.1] bg-[url('https://www.transparenttextures.com/patterns/carbon-fibre.png')]" />
    </div>
  );
};

export default WorkerSplash;
